INSERT INTO profiles(slug,name_en,name_ar,title_en,title_ar,org_en,org_ar,summary_en,summary_ar,body_en,body_ar,city,created_by,sector_id,status,published_at,consent_confirmed,featured,consent_note) VALUES('noura-al-safa','Noura Al Safa (Fictional)','نورة الصفا (شخصية خيالية)','Community initiative director','مدير مبادرات مجتمعية','Energy Demonstration Studio','استوديو تجريبي في مجال الطاقة','A fictional Saudi professional exploring practical ideas that connect people, knowledge and opportunity.','شخصية سعودية خيالية تستكشف أفكاراً عملية تجمع بين الناس والمعرفة والفرص. أُعدّ هذا الملف لأغراض العرض فقط.','<p>This is a fictional profile created to demonstrate The Profilez editorial experience. It does not describe a real person.</p><p>Noura Al Safa works with a small demonstration team to explore new ways of sharing knowledge across Saudi communities.</p><h2>Building with purpose</h2><p>The team values careful listening, thoughtful experiments and meaningful collaboration. Every project begins with a conversation.</p><ul><li>Support emerging talent</li><li>Share practical knowledge</li><li>Build lasting connections</li></ul>','<p>هذا ملف تعريفي خيالي أُعدّ لعرض تجربة ذا بروفايلز التحريرية، ولا يمثّل شخصاً حقيقياً.</p><p>يعمل فريق تجريبي صغير على استكشاف طرق جديدة لتبادل المعرفة بين المجتمعات في المملكة العربية السعودية، مع الاهتمام بالاحتياجات المحلية.</p><h2>العمل من أجل أثر مستدام</h2><p>يؤمن الفريق بأهمية الإصغاء والتجربة المدروسة والتعاون المثمر. وتبدأ كل مبادرة بحوار مفتوح يتيح للجميع المشاركة وصياغة الخطوة التالية.</p><ul><li>دعم المواهب الناشئة</li><li>مشاركة المعرفة العملية</li><li>بناء علاقات مستدامة</li></ul>','riyadh','seed@example.test',1,'published',CURRENT_TIMESTAMP,1,1,'Fictional demonstration profile; not a real person.');
